CREATE TEMPORARY VIEW dws_advv_request_raw_${grass_region_without_quote} AS
SELECT
    user_id
    ,feature_group
    ,product_type
    ,voucher_type
    ,ads_id
    ,item_id
    ,campaign_id
    ,request_id 

    ,sum(revenue_usd) as revenue_usd
    ,sum(broad_gmv_usd) as broad_gmv_usd
    ,sum(ads_order_cnt) as ads_order_cnt
    ,sum(ads_broad_order_cnt) AS ads_broad_order_cnt
    ,sum(ads_gmv_usd) as ads_gmv_usd
    ,sum(target_cir) as target_cir
    ,sum(direct_advv_cost) as direct_advv_cost
    ,sum(broad_advv_cost) as broad_advv_cost
    ,sum(direct_advv_gmv) as direct_advv_gmv
    ,sum(broad_advv_gmv) as broad_advv_gmv
    ,max(sum_deduction_price_usd) as sum_deduction_price_usd
    ,max(sum_bid_price_usd) as sum_bid_price_usd
    ,max(cnt_deduction_price) as cnt_deduction_price
    ,max(cnt_bid_price) as cnt_bid_price
    ,max(padvv) as padvv_cost
    ,sum(broad_advv_cost_excl_outlier) as broad_advv_cost_excl_outlier
    ,sum(broad_advv_cost_7d) as broad_advv_cost_7d
    ,sum(deepadvv) as deepadvv
FROM 
    srdi_mart.dws_sr_data_warehouse_ads_request_benchmark_advv_1d a
    lateral view explode(feature_groups) as feature_group
    lateral view explode(product_types) as product_type
    lateral view explode(voucher_types) as voucher_type
WHERE 
    local_date = ${local_date}
    AND grass_region = ${grass_region}
    AND user_id > 0
    AND (
        product_type != '__ALL__'
        or (product_type = '__ALL__' and voucher_type = '__ALL__')
    )

GROUP BY 
    1,2,3,4,5,6,7,8; 
    
--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_advv_abs_${grass_region_without_quote} AS
SELECT
    user_id
    ,feature_group

    ,IF(sum(ads_order_cnt) = 0, 0, sum(ads_gmv_usd) / sum(ads_order_cnt)) as direct_abs
    ,IF(sum(ads_broad_order_cnt) = 0, 0, sum(broad_gmv_usd) / sum(ads_broad_order_cnt))  as broad_abs 
FROM 
    dws_advv_request_raw_${grass_region_without_quote}
WHERE 
    product_type = '__ALL__'
    and voucher_type = '__ALL__'
GROUP BY 
    1,2;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_advv_request_${grass_region_without_quote} AS
SELECT
/*+ BROADCAST(c,d) */
    a.user_id
    ,a.feature_group
    ,product_type
    ,voucher_type
    ,IF(a.feature_group = 'Search', 'Search', 'RCMD') AS domain

    ,sum(revenue_usd) as revenue_usd
    ,sum(broad_gmv_usd) as broad_gmv_usd
    ,sum(ads_gmv_usd) as ads_gmv_usd
    ,sum(target_cir) as target_cir
    ,count(target_cir) as target_cir_cnt
    ,sum(direct_advv_cost) as direct_advv_cost
    ,sum(broad_advv_cost) as broad_advv_cost
    ,sum(direct_advv_gmv) as direct_advv_gmv
    ,sum(broad_advv_gmv) as broad_advv_gmv
    ,sum(sum_deduction_price_usd) as sum_deduction_price_usd
    ,sum(sum_bid_price_usd) as sum_bid_price_usd
    ,sum(cnt_deduction_price) as cnt_deduction_price
    ,sum(cnt_bid_price) as cnt_bid_price
    ,sum(padvv_cost) as padvv_cost
    ,sum(broad_advv_cost_excl_outlier) as broad_advv_cost_excl_outlier
    ,sum(broad_advv_cost_7d) as broad_advv_cost_7d
    ,sum(deepadvv) as deepadvv

    ,sum(if (direct_abs <= d.abs_999, revenue_usd, null)) as revenue_usd_999
    ,sum(if (broad_abs <= c.abs_999, broad_gmv_usd, null)) as broad_gmv_usd_999
    ,sum(if (direct_abs <= d.abs_999, ads_gmv_usd, null)) as ads_gmv_usd_999
    ,sum(if (direct_abs <= d.abs_999, target_cir, null)) as target_cir_999
    ,count(if (direct_abs <= d.abs_999, target_cir, null)) as target_cir_cnt_999
    ,sum(if (direct_abs <= d.abs_999, direct_advv_cost, null)) as direct_advv_cost_999
    ,sum(if (broad_abs <= c.abs_999, broad_advv_cost, null)) as broad_advv_cost_999
    ,sum(if (direct_abs <= d.abs_999, direct_advv_gmv, null)) as direct_advv_gmv_999
    ,sum(if (broad_abs <= c.abs_999, broad_advv_gmv, null)) as broad_advv_gmv_999
    ,sum(if (direct_abs <= d.abs_999, sum_deduction_price_usd, null)) as sum_deduction_price_usd_999
    ,sum(if (direct_abs <= d.abs_999, sum_bid_price_usd, null)) as sum_bid_price_usd_999
    ,sum(if (direct_abs <= d.abs_999, cnt_deduction_price, null)) as cnt_deduction_price_999
    ,sum(if (direct_abs <= d.abs_999, cnt_bid_price, null)) as cnt_bid_price_999
    ,sum(if (direct_abs <= d.abs_999, padvv_cost, null)) as padvv_cost_999
    ,sum(if (broad_abs <= c.abs_999, broad_advv_cost_excl_outlier, null))  as broad_advv_cost_excl_outlier_999
    ,sum(if (broad_abs <= c.abs_999, broad_advv_cost_7d, null))as broad_advv_cost_7d_999
    ,sum(if (broad_abs <= c.abs_999, deepadvv, null)) as deepadvv_999
FROM 
    dws_advv_request_raw_${grass_region_without_quote} a
    LEFT JOIN dws_advv_abs_${grass_region_without_quote} e 
        ON a.user_id = e.user_id
        AND a.feature_group = e.feature_group
    LEFT JOIN ads_outlier_broad_${grass_region_without_quote} c
    ON a.feature_group = c.feature_group
    LEFT JOIN ads_outlier_direct_${grass_region_without_quote} d
    ON a.feature_group = d.feature_group
GROUP BY
    1,2,3,4,5;

--sql_divide_splitter--

CACHE TABLE ads_exp_${grass_region_without_quote} AS 
SELECT
    b.exp_group_id
    ,a.feature_group
    ,product_type
    ,voucher_type
    ,b.domain

    ,sum(revenue_usd) as revenue_usd
    ,sum(broad_gmv_usd) as broad_gmv_usd
    ,sum(ads_gmv_usd) as ads_gmv_usd
    ,sum(target_cir) / sum(target_cir_cnt) as target_cir
    ,sum(direct_advv_cost) as direct_advv_cost
    ,sum(broad_advv_cost) as broad_advv_cost
    ,sum(direct_advv_gmv) as direct_advv_gmv
    ,sum(broad_advv_gmv) as broad_advv_gmv
    ,sum(revenue_usd) / sum(direct_advv_cost) as direct_cost_ratio
    ,sum(revenue_usd) / sum(broad_advv_cost) as broad_cost_ratio
    ,case when product_type in ('manual_cpc','manual_ecpc','itemboost','new_product_boost','video_max_view') then sum(ads_gmv_usd)/sum(ads_gmv_usd)
        else sum(ads_gmv_usd)/sum(direct_advv_gmv) end as direct_gmv_ratio
    ,case when product_type in ('manual_cpc','manual_ecpc','itemboost','new_product_boost','video_max_view') then sum(broad_gmv_usd)/sum(broad_gmv_usd)
        else sum(broad_gmv_usd)/sum(broad_advv_gmv) end as broad_gmv_ratio
    ,sum(sum_deduction_price_usd)/sum(cnt_deduction_price) as avg_deduction_price_usd
    ,sum(sum_bid_price_usd)/sum(cnt_bid_price) as avg_bid_price_usd
    ,sum(sum_deduction_price_usd) as sum_deduction_price_usd
    ,sum(sum_bid_price_usd) as sum_bid_price_usd
    ,sum(cnt_deduction_price) as cnt_deduction_price
    ,sum(cnt_bid_price) as cnt_bid_price
    ,(sum(sum_deduction_price_usd)/sum(cnt_deduction_price))/(sum(sum_bid_price_usd)/sum(cnt_bid_price)) as deduction_bid_ratio
    ,sum(padvv_cost) as padvv_cost
    ,sum(broad_advv_cost_excl_outlier) as broad_advv_cost_excl_outlier
    ,sum(broad_advv_cost_7d) as broad_advv_cost_7d
    ,sum(deepadvv) as deepadvv

    ,sum(revenue_usd_999) as revenue_usd_999
    ,sum(broad_gmv_usd_999) as broad_gmv_usd_999
    ,sum(ads_gmv_usd_999) as ads_gmv_usd_999
    ,sum(target_cir_999) / sum(target_cir_cnt_999) as target_cir_999
    ,sum(direct_advv_cost_999) as direct_advv_cost_999
    ,sum(broad_advv_cost_999) as broad_advv_cost_999
    ,sum(direct_advv_gmv_999) as direct_advv_gmv_999
    ,sum(broad_advv_gmv_999) as broad_advv_gmv_999
    ,sum(revenue_usd_999) / sum(direct_advv_cost_999) as direct_cost_ratio_999
    ,sum(revenue_usd_999) / sum(broad_advv_cost_999) as broad_cost_ratio_999
    ,case when product_type in ('manual_cpc','manual_ecpc','itemboost','new_product_boost','video_max_view') then sum(ads_gmv_usd_999) / sum(ads_gmv_usd_999)
        else sum(ads_gmv_usd_999) / sum(direct_advv_gmv_999) end as direct_gmv_ratio_999
    ,case when product_type in ('manual_cpc','manual_ecpc','itemboost','new_product_boost','video_max_view') then sum(broad_gmv_usd_999) / sum(broad_gmv_usd_999)
        else sum(broad_gmv_usd_999) /sum(broad_advv_gmv_999)  end as broad_gmv_ratio_999
    ,sum(sum_deduction_price_usd_999) /sum(cnt_deduction_price_999) as avg_deduction_price_usd_999
    ,sum(sum_bid_price_usd_999) /sum(cnt_bid_price_999) as avg_bid_price_usd_999
    ,sum(sum_deduction_price_usd_999) as sum_deduction_price_usd_999
    ,sum(sum_bid_price_usd_999) as sum_bid_price_usd_999
    ,sum(cnt_deduction_price_999) as cnt_deduction_price_999
    ,sum(cnt_bid_price_999) as cnt_bid_price_999
    ,(sum(sum_deduction_price_usd_999) /sum(cnt_deduction_price_999) )/(sum(sum_bid_price_usd_999) /sum(cnt_bid_price_999) ) as deduction_bid_ratio_999
    ,sum(padvv_cost_999) as padvv_cost_999
    ,sum(broad_advv_cost_excl_outlier_999)  as broad_advv_cost_excl_outlier_999
    ,sum(broad_advv_cost_7d_999)as broad_advv_cost_7d_999
    ,sum(deepadvv_999) as deepadvv_999
FROM 
    dws_advv_request_${grass_region_without_quote}  a 
    INNER JOIN user_exp_${grass_region_without_quote} b
        ON a.user_id = b.user_id
        -- AND a.domain = b.domain
GROUP BY
    1,2,3,4,5;

